/**
 * Test flow for lookUpEmailAttachments action
 * Demonstrates looking up email attachments
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testLookUpEmailAttachments = Flow(
    {
        $id: Now.ID['test_look_up_email_attachments_flow'],
        name: 'Test Look Up Email Attachments',
        description: 'Tests the lookUpEmailAttachments core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_look_up_email_attachments_trigger'] },
        {
            table: 'sys_email',
            condition: 'type=received',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.lookUpEmailAttachments,
            { $id: Now.ID['test_look_up_email_attachments_action'] },
            {
                email_record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_look_up_email_attachments_log'] },
            {
                log_level: 'info',
                log_message: `lookUpEmailAttachments outputs: email_attachments=${wfa.dataPill(result.email_attachments, 'reference')}`,
            }
        )
    }
)
